//! The engine-embedded `core` interface generated by `scripts/gen_core_interface.py`
//! must parse cleanly under the native declaration grammar. Every declaration is a
//! body-less `native fn` with an effect clause.

use orna_syntax::{Declaration, parse_module};

const CORE_FILES: &[(&str, &str)] = &[
    (
        "core.orna",
        include_str!("../../orna-hir/interface/core.orna"),
    ),
    (
        "core/bits.orna",
        include_str!("../../orna-hir/interface/core/bits.orna"),
    ),
    (
        "core/collection.orna",
        include_str!("../../orna-hir/interface/core/collection.orna"),
    ),
    (
        "core/hash.orna",
        include_str!("../../orna-hir/interface/core/hash.orna"),
    ),
    (
        "core/stats.orna",
        include_str!("../../orna-hir/interface/core/stats.orna"),
    ),
    (
        "core/text.orna",
        include_str!("../../orna-hir/interface/core/text.orna"),
    ),
    (
        "core/time.orna",
        include_str!("../../orna-hir/interface/core/time.orna"),
    ),
    (
        "core/encoding/base64.orna",
        include_str!("../../orna-hir/interface/core/encoding/base64.orna"),
    ),
    (
        "core/encoding/json.orna",
        include_str!("../../orna-hir/interface/core/encoding/json.orna"),
    ),
    (
        "core/encoding/orna.orna",
        include_str!("../../orna-hir/interface/core/encoding/orna.orna"),
    ),
    (
        "core/encoding/ovb.orna",
        include_str!("../../orna-hir/interface/core/encoding/ovb.orna"),
    ),
];

/// Native declarations per file, matching `grep -c '^pub native fn'` on each generated file.
const EXPECTED_NATIVES: &[(&str, usize)] = &[
    ("core.orna", 4),
    ("core/bits.orna", 6),
    ("core/collection.orna", 27),
    ("core/hash.orna", 5),
    ("core/stats.orna", 14),
    ("core/text.orna", 10),
    ("core/time.orna", 6),
    ("core/encoding/base64.orna", 2),
    ("core/encoding/json.orna", 3),
    ("core/encoding/orna.orna", 2),
    ("core/encoding/ovb.orna", 2),
];

/// The 1-based line and text of the source at each diagnostic's start offset.
fn located(source: &str, diagnostics: &[orna_syntax::SyntaxDiagnostic]) -> Vec<String> {
    diagnostics
        .iter()
        .map(|diagnostic| {
            let offset = diagnostic.span.start.min(source.len());
            let line = source[..offset].matches('\n').count() + 1;
            let text = source.lines().nth(line - 1).unwrap_or("");
            format!(
                "{}:{} {} [{}]",
                line,
                diagnostic.code,
                diagnostic.message,
                text.trim()
            )
        })
        .collect()
}

#[test]
fn generated_core_interface_parses_without_diagnostics() {
    for (path, source) in CORE_FILES {
        let parsed = parse_module(source);
        assert!(
            parsed.is_ok(),
            "{path} should parse, got {:#?}",
            located(source, &parsed.diagnostics)
        );
    }
}

#[test]
fn generated_core_interface_declares_expected_natives_with_effect_clauses() {
    for (path, source) in CORE_FILES {
        let parsed = parse_module(source);
        let effects: Vec<_> = parsed
            .value
            .items
            .iter()
            .filter_map(|item| match &item.declaration {
                Declaration::Native { effects, .. } => Some(effects),
                _ => None,
            })
            .collect();
        let expected = EXPECTED_NATIVES
            .iter()
            .find(|(name, _)| name == path)
            .map(|(_, count)| *count)
            .unwrap_or_else(|| panic!("no expected count for {path}"));
        assert_eq!(effects.len(), expected, "{path} native count");
        assert!(
            effects.iter().all(|effects| effects.is_some()),
            "{path} effect clauses"
        );
    }
}
